","test":"test_structure.sql; test_rules.sql"},{"name":"NA_MESSAGE","position":21,"source_type":"text","source_definition":"`NA_MESSAGE` text DEFAULT NULL COMMENT ''Task message or concise error summary''","type":"text","nullable":true,"default":null,"generated":false,"on_update":false,"collation":"general_ci","test":"test_structure.sql; test_rules.sql"},{"name":"NA_ERROR_CODE","position":22,"source_type":"varchar(64)","source_definition":"`NA_ERROR_CODE` varchar(64) DEFAULT NULL COMMENT ''Stable canonical error code''","type":"character varying(64)","nullable":true,"default":null,"generated":false,"on_update":false,"collation":"general_ci","test":"test_structure.sql; test_rules.sql"},{"name":"NA_ERROR_DETAIL","position":23,"source_type":"text","source_definition":"`NA_ERROR_DETAIL` text DEFAULT NULL COMMENT ''Useful technical context for one error''","type":"text","nullable":true,"default":null,"generated":false,"on_update":false,"collation":"general_ci","test":"test_structure.sql; test_rules.sql"},{"name":"NU_ERROR_CLASSIFIER_VERSION","position":24,"source_type":"smallint(6)","source_definition":"`NU_ERROR_CLASSIFIER_VERSION` smallint(6) DEFAULT NULL COMMENT ''Version of the classifier used to populate the structured error fields''","type":"smallint","nullable":true,"default":null,"generated":false,"on_update":false,"collation":null,"test":"test_structure.sql; test_rules.sql"},{"name":"IS_PAYLOAD_DELETED","position":25,"source_type":"tinyint(1)","source_definition":"`IS_PAYLOAD_DELETED` tinyint(1) NOT NULL DEFAULT 0","type":"smallint","nullable":false,"default":"0","generated":false,"on_update":false,"collation":null,"test":"test_structure.sql; test_rules.sql"},{"name":"DT_PAYLOAD_DELETED","position":26,"source_type":"datetime","source_definition":"`DT_PAYLOAD_DELETED` datetime DEFAULT NULL","type":"timestamp(0) without time zone","nullable":true,"default":null,"generated":false,"on_update":false,"collation":null,"test":"test_structure.sql; test_rules.sql"}],"prim